  const resumed = await loadOrCreateContextFromPersistentStore(pid7);
  assert2(resumed.projectGoal.includes("Resume"), "resume restores the project goal");
  assert2(resumed.fileMap.size === 3, "resume restores the fileMap", "size=" + resumed.fileMap.size);
  assert2(resumed.keyDecisions.length === 2, "resume restores key decisions");
  assert2(resumed.compactionLevel === 2, "resume restores compaction level", String(resumed.compactionLevel));
  console.log("\n=== 8. COMPACTION TELEMETRY ===");
  await sleep(50);
  const events = await readAllEvents(pid2);
  const compEvents = events.filter((e) => e.type === "compaction");
  assert2(compEvents.length > 0, "compaction events are emitted to telemetry", "count=" + compEvents.length);
  if (compEvents.length > 0) {
    const last = compEvents[compEvents.length - 1];
    const d = last.data || {};
    assert2(d.trigger === "step-count" || d.trigger === "manual", "event carries the honest trigger", String(d.trigger));
    assert2(typeof d.levelName === "string" && d.levelName.length > 0, "event carries the compaction level name", String(d.levelName));
    assert2(d.preservedItems && d.preservedItems.fileMapFiles >= 0, "event carries preservedItems payload");
  }
  console.log("\n=== CLEANUP ===");
  const benchIds = [pid1, pid2, pid3, pid4, SMART_DIR, pid6, pid7];
